package com.jadhavr.erp.email.service;import com.fasterxml.jackson.databind.ObjectMapper;import com.jadhavr.erp.email.config.MailProperties;import com.jadhavr.erp.email.entity.EmailNotification;import com.jadhavr.erp.email.repository.EmailNotificationRepository;import com.jadhavr.erp.user.entity.User;import org.junit.jupiter.api.*;import org.mockito.*;import static org.mockito.Mockito.*;class EmailNotificationServiceImplTest{@Mock EmailNotificationRepository repo;AutoCloseable mocks;EmailNotificationServiceImpl service;@BeforeEach void setup(){mocks=MockitoAnnotations.openMocks(this);service=new EmailNotificationServiceImpl(repo,new MailProperties(),new ObjectMapper(),new TemplateDataCipher("test-secret-for-email-encryption"),"http://localhost:5173");}@AfterEach void close()throws Exception{mocks.close();}@Test void queuesEncryptedIdempotentUserCreatedNotification(){User u=new User();u.setId(42L);u.setFullName("Test User");u.setEmail("test@example.com");service.queueUserCreatedEmail(u);ArgumentCaptor<EmailNotification>c=ArgumentCaptor.forClass(EmailNotification.class);verify(repo).save(c.capture());Assertions.assertFalse(c.getValue().getTemplateData().contains("Test User"));Assertions.assertEquals("USER_CREATED:42:test@example.com",c.getValue().getIdempotencyKey());}@Test void duplicateEventIsNotQueued(){when(repo.existsByIdempotencyKey("USER_CREATED:42:test@example.com")).thenReturn(true);User u=new User();u.setId(42L);u.setFullName("Test User");u.setEmail("test@example.com");service.queueUserCreatedEmail(u);verify(repo,never()).save(any());}}
